import re
import json
import time
import logging
from typing import Optional, Dict, Any

logger = logging.getLogger(__name__)

# IoT Device Message Handler for industrial sensor network
# Validates incoming MQTT-style messages from field devices

# Pattern validates device telemetry format: key=value pairs separated by semicolons
# with optional nested groupings in parentheses
DEVICE_TELEMETRY_PATTERN = re.compile(
    r'^(([a-zA-Z0-9_]+)=(([a-zA-Z0-9._]+|\(([a-zA-Z0-9._]+;)*[a-zA-Z0-9._]+\));)*([a-zA-Z0-9_]+)=(([a-zA-Z0-9._]+|\(([a-zA-Z0-9._]+;)*[a-zA-Z0-9._]+\)))$'
)

# Secondary pattern for firmware version strings
FIRMWARE_VERSION_PATTERN = re.compile(
    r'^(v?\d+\.)*\d+(-[a-zA-Z]+(\.\d+)*)*$'
)

# Alert threshold pattern - validates threshold expressions
THRESHOLD_PATTERN = re.compile(
    r'^((\d+\.?\d*)(\s*[<>]=?\s*(\d+\.?\d*))*)(\s*&&\s*((\d+\.?\d*)(\s*[<>]=?\s*(\d+\.?\d*))*))*$'
)


class DeviceMessageHandler:
    def __init__(self, device_registry: Dict[str, Any]):
        self.device_registry = device_registry
        self.message_count = 0
        self.last_processed = None

    def validate_telemetry_payload(self, payload: str) -> bool:
        """Validate telemetry data format from field devices."""
        if not payload or len(payload) > 4096:
            return False
        match = DEVICE_TELEMETRY_PATTERN.match(payload)
        return match is not None

    def validate_firmware_version(self, version: str) -> bool:
        """Validate firmware version string format."""
        if not version or len(version) > 128:
            return False
        match = FIRMWARE_VERSION_PATTERN.match(version)
        return match is not None

    def validate_threshold_expr(self, expr: str) -> bool:
        """Validate alert threshold expression."""
        if not expr or len(expr) > 512:
            return False
        match = THRESHOLD_PATTERN.match(expr)
        return match is not None

    def process_message(self, raw_message: bytes) -> Optional[Dict[str, Any]]:
        """Process incoming device message."""
        try:
            message = json.loads(raw_message.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            logger.warning(f"Failed to decode message: {e}")
            return None

        device_id = message.get('device_id')
        if not device_id or device_id not in self.device_registry:
            logger.warning(f"Unknown device: {device_id}")
            return None

        msg_type = message.get('type')

        if msg_type == 'telemetry':
            payload = message.get('payload', '')
            if not self.validate_telemetry_payload(payload):
                logger.warning(f"Invalid telemetry from {device_id}")
                return None
            self.message_count += 1
            self.last_processed = time.time()
            return {'status': 'accepted', 'device_id': device_id, 'type': 'telemetry'}

        elif msg_type == 'firmware_check':
            version = message.get('version', '')
            if not self.validate_firmware_version(version):
                logger.warning(f"Invalid firmware version from {device_id}")
                return None
            return {'status': 'accepted', 'device_id': device_id, 'type': 'firmware_check'}

        elif msg_type == 'threshold_update':
            expr = message.get('expression', '')
            if not self.validate_threshold_expr(expr):
                logger.warning(f"Invalid threshold from {device_id}")
                return None
            return {'status': 'accepted', 'device_id': device_id, 'type': 'threshold_update'}

        else:
            logger.warning(f"Unknown message type: {msg_type}")
            return None


def lambda_handler(event, context):
    """AWS Lambda entry point for IoT rule action."""
    registry = event.get('device_registry', {})
    handler = DeviceMessageHandler(registry)
    results = []
    for record in event.get('records', []):
        import base64
        raw = base64.b64decode(record['data'])
        result = handler.process_message(raw)
        results.append(result)
    return {'processed': len(results), 'results': results}
